function ymTile(canvas,T){
  const ctx=canvas.getContext('2d');
  if(!ctx)return;
  ctx.setTransform(3,0,0,3,0,0);
  ctx.clearRect(0,0,40,40);
  const wash=ctx.createLinearGradient(0,0,40,40);
  wash.addColorStop(0,'#fff0c7');wash.addColorStop(1,'#d9aa6e');
  ctx.fillStyle=wash;ctx.fillRect(0,0,40,40);
  ctx.strokeStyle='#7f5732';ctx.lineWidth=.5;ctx.strokeRect(0,0,40,40);
  const edges=[[20,0],[40,20],[20,40],[0,20]];
  const rim=[[1.5,1.5,38.5,1.5],[38.5,1.5,38.5,38.5],[1.5,38.5,38.5,38.5],[1.5,1.5,1.5,38.5]];
  T.forEach((kind,i)=>{
    const [x,y]=edges[i];
    const [color,line,dash]=YM_STY[kind]||['#302218',2.5,''];
    ctx.beginPath();ctx.strokeStyle=color;ctx.lineWidth=line;
    ctx.setLineDash(dash?dash.split(' ').map(Number):[]);
    ctx.lineCap=kind===2||kind===4?'round':'butt';
    if(!kind){const [ax,ay,bx,by]=rim[i];ctx.moveTo(ax,ay);ctx.lineTo(bx,by);}
    else{
      ctx.moveTo(x,y);
      if(kind===2)ctx.quadraticCurveTo((x+20)/2+(i%2?0:4),(y+20)/2+(i%2?4:0),20,20);
      else ctx.lineTo(20,20);
    }
    ctx.stroke();
  });
  ctx.setLineDash([]);ctx.beginPath();ctx.arc(20,20,3.4,0,Math.PI*2);ctx.fillStyle='#eed8a4';ctx.fill();
  ctx.lineWidth=.7;ctx.strokeStyle='#604528';ctx.stroke();
}

