const board70Image=(key,name,alt='',cls='board70-icon')=>`<img class="${cls}" src="motion/revised/boards-70/${key}/${name}.webp" alt="${alt}" draggable="false">`;
function board70Sheet(key,content){
  return `<section class="xsheet adventure-board board70" data-board70="${key}" style="--board-scene:url('motion/revised/boards-70/${key}/scene.webp')">${content}</section>`;
}
function board70Staff(samples,{width=100,height=54,lines,notes,separators=[],kind=''}){
  const dots=notes.map(([x,y,v])=>`<i class="${v<0?'unknown':'note'}" style="left:${x/width*100}%;top:${y/height*100}%">${v<0?'؟':''}</i>`).join('');
  const rulings=lines.map(y=>`<b style="top:${y/height*100}%"></b>`).join('');
  const bars=separators.map(x=>`<u style="left:${x/width*100}%"></u>`).join('');
  return `<span class="board70-staff ${kind}" style="aspect-ratio:${width}/${height}" role="img" aria-label="النغمات ${samples.map(v=>v<0?'مفقودة':XAR(v+1)).join('، ')}">${rulings}${bars}${dots}</span>`;
}
function board70Canvas(canvas,w,h){
  canvas.width=w*2;canvas.height=h*2;
  const ctx=canvas.getContext('2d');
  ctx.scale(2,2);
  return ctx;
}

function board70Layers(P,canvas,W,Hh,H){
  const lay=P.ev.filter(e=>e.t==='L'),fs=P.ev.filter(e=>e.t==='F');
  const off=(li,x)=>fs.reduce((sum,f)=>sum+(li<=f.top&&x>f.x*W?10:0),0);
  const ctx=board70Canvas(canvas,W,H+8);
  ctx.strokeStyle='#3a2616';
  ctx.lineJoin='round';
  lay.forEach(e=>{
    const y=H-(e.i+1)*Hh, xs=[0,W*.25,W*.5,W*.75,W];
    const point=(x,base)=>[x,base-off(e.i,x)];
    const contour=[...xs.map(x=>point(x,y)),...xs.slice().reverse().map(x=>point(x,y+Hh))];
    ctx.beginPath();contour.forEach(([x,p],i)=>i?ctx.lineTo(x,p):ctx.moveTo(x,p));ctx.closePath();
    ctx.fillStyle=ALY_C[e.i];ctx.fill();ctx.stroke();
    ctx.save();ctx.clip();ctx.globalAlpha=.32;ctx.lineWidth=.7;
    for(let j=0;j<10;j++){
      const x=8+j*30,z=y+9+(j%3)*9;
      ctx.beginPath();ctx.moveTo(x,z);ctx.lineTo(x+17,z);ctx.stroke();
    }
    ctx.restore();ctx.fillStyle='#2d2018';ctx.font='bold 14px serif';ctx.fillText('أبجدهوز'[e.i],10,y+Hh/2+5);
  });
  function label(text,x,y){
    ctx.fillStyle='#f4e9cc';ctx.fillRect(x-12,y-10,24,15);ctx.strokeRect(x-12,y-10,24,15);
    ctx.fillStyle='#3a2616';ctx.font='bold 10px sans-serif';ctx.textAlign='center';ctx.fillText(text,x,y);
  }
  P.ev.filter(e=>e.t==='V').forEach(v=>{
    const x=v.x*W, top=H-(v.top+1)*Hh, d=H-top;
    const vein=new Path2D(`M${x-6} ${H}q8 -${d/3} -2 -${d*.6}t6 -${d*.4}h8q-8 ${d*.4} 2 ${d*.6}t-2 ${d*.4}z`);
    ctx.fillStyle=ALY_V[v.i];ctx.fill(vein);ctx.stroke(vein);label(XAR(v.i+1),x+4,top+14);
  });
  fs.forEach(f=>{
    const x=f.x*W,top=H-(f.top+1)*Hh;
    ctx.save();ctx.setLineDash([6,3]);ctx.lineWidth=2.4;ctx.beginPath();ctx.moveTo(x,H);ctx.lineTo(x-6,top);ctx.stroke();ctx.restore();
    label(`شق ${XAR(f.i+1)}`,x-7,top+7);
  });
}

